json.dump(job, open(os.path.join(D, 'picks_bz.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
for m in msgs:
    q = re.search(r'<blockquote>(.*)</blockquote>', m['text'], re.S).group(1)
    print(m['pid'], 'подпись', len(re.sub(r'<[^>]+>', '', m['text'])), 'цитата', len(q))
